import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"卦材第三","description":"杭氏易學 - 卦材第三","frontmatter":{"title":"卦材第三","description":"杭氏易學 - 卦材第三"},"headers":[],"relativePath":"classics/hangshi/004.md","filePath":"classics/hangshi/004.md"}'),i={name:"classics/hangshi/004.md"};function c(o,a,l,d,p,h){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"卦材第三",tabindex:"-1"},[n("卦材第三 "),e("a",{class:"header-anchor",href:"#卦材第三","aria-label":"Permalink to “卦材第三”"},"​")],-1),e("p",null,"程朱《傳》、《義》，宗王《注》，其釋《彖》、《象》，均以卦德卦義卦名為言。來知德氏《集註》言性情，以內卦為性，外卦為情，意非不當，要皆強為之名。實則孔子《系傳》、《說卦》，當名辨物，已有定稱。《傳》曰：“彖者，才也。才也者，材也。”言材則體用皆賅，德性兼備無餘蘊矣。《說卦》“雷動風散”，“乾健坤順”兩章，皆言八卦之材。知八卦象之材，而後知六十四卦因重交互，無不各因其材。而辨其情偽吉凶，銖兩悉稱，名實相副。《彖》、《象》傳贊，亦無不各因其材以為之辭，無一字之虛設焉。學者宜詳玩經文，而合之於象，準之於數，融會貫通，由一卦以推各卦，而觀一卦，更必遍取各卦，參互比例，而後能得其真確之意義。不可因字義註釋之已明，而不復研求深意之所在焉。",-1),e("p",null,"健順動入陷麗止說，各一字概一卦之德性功用。而父母男女，亦各因其名，以定一卦之分際。今皆謂之材者，以六十四卦之《彖》、《象》，無不合內外兩卦之材以命辭。而一卦六爻，及內外中爻，亦無不取材於是。《傳》曰：“君子觀其彖辭，則思過半矣。”彖辭因材而施之辭也，且不特內外卦為然。即卦中之一爻，為何卦之爻，即具何卦之材。如為坎爻必有陷義，或險義。為離爻者，必具明義，或麗義。惟乾坤兩卦，不以爻言。而《雜卦》之“震起兌見巽伏艮止”，此“起止見伏”四字，尤為八卦變化之門。觀象玩辭，均不可不於此鄭重注意也。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
